// Loop Unrolling (Reduces branch checks overhead)
// Compiler transforms N checks into N/K checks
// K=4 in this example
for (int i = 0; i < N; i += 4) {
    A[i]   = F(B[i]);
    A[i+1] = F(B[i+1]);
    A[i+2] = F(B[i+2]);
    A[i+3] = F(B[i+3]);
}
// Requires epilogue loop for N % 4 != 0 remainder

// Loop Invariant Code Motion (LACM)
// Moves constant computations outside the loop check
int calculate_limit(int n, int k) {
    return (n * k) + 5;
}

void process(int N, int K, int* arr) {
    int limit = calculate_limit(N, K); // Invariant moved
    for (int i = 0; i < limit; ++i) {
        arr[i] = arr[i] * 2;
    }
}

// Branch Prediction Hint (GCC/Clang extension)
// Helps the hardware predict control flow path
#define likely(x)   __builtin_expect(!!(x), 1)
#define unlikely(x) __builtin_expect(!!(x), 0)

void error_check(int status) {
    if (unlikely(status < 0)) {
        // This block rarely executes (misprediction cost minimized)
        handle_error(status);
    }
}
